// src/components/LoginModal.js
import React, { useState } from 'react';

function LoginModal({ closeModal }) {
  const [isLogin, setIsLogin] = useState(true); // Quản lý trạng thái Đăng nhập/Đăng ký
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };
  
  const handleSubmit = (e) => {
    e.preventDefault();
    // TODO: Thêm logic gọi API tại đây
    if (isLogin) {
        console.log("Đăng nhập:", formData);
        alert("Xử lý Đăng nhập...");
    } else {
        console.log("Đăng ký:", formData);
        alert("Xử lý Đăng ký...");
    }
    // closeModal(); // Đóng modal sau khi xử lý thành công
  };

  return (
    // Backdrop: Click ra ngoài để đóng Modal
    <div className="modal-backdrop" onClick={closeModal}> 
      <div 
        className="login-modal-content" 
        onClick={(e) => e.stopPropagation()} // Ngăn chặn sự kiện click lan ra Backdrop
      >
        <div className="modal-header">
          {/* Tùy chỉnh tiêu đề theo trạng thái */}
          <h2>{isLogin ? "ĐĂNG NHẬP TÀI KHOẢN" : "TẠO TÀI KHOẢN"}</h2>
          <p>{isLogin ? "Nhập email và mật khẩu của bạn:" : "Vui lòng điền thông tin:"}</p>
        </div>
        
        <form onSubmit={handleSubmit}>
          <input 
            type="text" 
            name="email"
            placeholder="Nhập email hoặc số điện thoại" 
            value={formData.email}
            onChange={handleChange}
            required
          />
          <input 
            type="password" 
            name="password"
            placeholder="Mật khẩu" 
            value={formData.password}
            onChange={handleChange}
            required
          />
          
          {/* Nút Đăng nhập / Đăng ký chính */}
          <button type="submit" className="btn-main-action">
            {isLogin ? "ĐĂNG NHẬP" : "ĐĂNG KÝ"}
          </button>
        </form>
        
        <div className="modal-footer-links">
          {isLogin ? (
            // Nội dung khi Đăng nhập
            <>
              <p>Khách hàng mới? <button className="link-btn" onClick={() => setIsLogin(false)}>Tạo tài khoản</button></p>
              <p>Quên mật khẩu? <button className="link-btn">Khôi phục mật khẩu</button></p>
            </>
          ) : (
            // Nội dung khi Đăng ký
            <p>Đã có tài khoản? <button className="link-btn" onClick={() => setIsLogin(true)}>Đăng nhập ngay</button></p>
          )}
        </div>
      </div>
    </div>
  );
}

export default LoginModal;
